```js
/** shell 段切分：&&/||/;/| 分隔符与换行；引号内的分隔符不切段 */
const shellSegments = (s) => {
  const str = String(s);
  const segs = [];
  let cur = "";
  let q = "";
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const two = str.slice(i, i + 2);
    if (q) {
      cur += ch;
      if (ch === q) q = "";
    } else if (ch === '"' || ch === "'") {
      cur += ch;
      q = ch;
    } else if (two === "&&" || two === "||") {
      segs.push(cur);
      cur = "";
      i++;
    } else if (ch === ";" || ch === "|" || ch === "\n") {
      segs.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  segs.push(cur);
  return segs;
};
```

