const tokenize = (s) => {
  const re = /"[^"]*"|'[^']*'|\S+/g;
  const out = [];
  let last = -1;
  for (const m of String(s).matchAll(re)) {
    const tok = m[0].replaceAll('"', "").replaceAll("'", "");
    // 相邻 match 之间无空白 = shell 词内拼接（"comm"it 即 commit），并回同一 token
    if (m.index === last) out[out.length - 1] += tok;
    else out.push(tok);
    last = m.index + m[0].length;
  }
  return out;
};

